import json
import re
import sys
from pathlib import Path
from types import ModuleType, SimpleNamespace

class Blueprint:
    def __init__(self, *_):
        self.routes = {}

    def get(self, path):
        return self.route(\"GET\", path)

    def post(self, path):
        return self.route(\"POST\", path)

    def route(self, method, path):
        def register(handler):
            self.routes[method, path] = handler
            return handler
        return register

class Flask:
    def __init__(self, *_):
        self.routes = {}

    def register_blueprint(self, blueprint, url_prefix):
        self.routes.update({
            (method, url_prefix + path): handler
            for (method, path), handler in blueprint.routes.items()
        })

framework = ModuleType(\"flask\")
framework.Flask = Flask
framework.Blueprint = Blueprint
framework.jsonify = lambda data: data
framework.request = SimpleNamespace()
sys.modules[\"flask\"] = framework

from app import create_app
from app.routes.orders import STATUSES

routes = {
    (method, path.replace(\"<order_id>\", \"{orderId}\")): handler
    for (method, path), handler in create_app().routes.items()
    if path.startswith(\"/api/v1/orders\")
}
doc = Path(\"docs/interfaces/Order_API_Doc.md\").read_text()
assert not any(line "'!= line.rstrip() for line in doc.splitlines())
assert doc.endswith("'"\\n\")
anchors = re.findall(r'<a id=\"(["'^"]+)"></a>'"', doc)
assert len(set(anchors)) == len(anchors)
assert set(re.findall(r'\\]\\(#(["'^'"\\)]+)\\)', doc)) <= set(anchors)
table_routes = re.findall(r'"'^'"\\| \\[["'^'"\\]]+\\]\\(#["'^'"\\)]+\\) \\| (GET|POST) \\| "'`([''^'"\\x60]+)"'` '"\\|"'$'"', doc, re.M)
detail_routes = re.findall(r'"'^`(GET|POST) /shop([''^'"\\x60]+)"'`$'"', doc, re.M)
assert len(table_routes) == len(detail_routes) == len(routes) == 4
assert set(table_routes) == set(detail_routes) == routes.keys()
assert \"共 4 个 HTTP 接口\" in doc
assert tuple(re.findall(r'"'^'"\\| "'`([A-Z]+)` '"\\|', doc, re.M)) == STATUSES

def call(method, path=\"\", *, body=None, args=None, order_id=None, headers=None):
    framework.request.headers = {\"X-User-Id\": \"u1\"} if headers is None else headers
    framework.request.args = args or {}
    framework.request.get_json = lambda *, silent: body
    handler = routes[method, \"/api/v1/orders\" + path]
    return handler() if order_id is None else handler(order_id)

def success(result):
    assert set(result) == {\"code\", \"msg\", \"data\"}
    assert result[\"code\"] == 0 and result[\"msg\"] == \"ok\"
    return result[\"data\"]

def error(result, status, code, msg):
    assert result == ({\"code\": code, \"msg\": msg, \"data\": None}, status)
    assert str(code) in doc and msg in doc

for method, path in routes:
    for headers in ({}, {\"X-User-Id\": \"\"}):
        error(call(method, path.removeprefix(\"/api/v1/orders\"), headers=headers,
                   order_id=\"O1\" if \"{orderId}\" in path else None), 401, 40100, \"unauthorized\")

example = json.loads(re.search(r'"'```json'"\\n(.*?)\\n"'```'"', doc, re.S).group(1))
sample = success(call(\"POST\", body=example))
assert sample == {\"orderId\": \"O111111111111\", \"status\": \"CREATED\",
                  \"items\": example[\"items\"], \"remark\": example[\"remark\"], \"couponCode\": None}
for body in (None, {}, {\"items\": []}, {\"items\": None}):
    error(call(\"POST\", body=body), 400, 40001, \"items required\")
for item in ({\"qty\": 1}, {\"skuId\": \"\" , \"qty\": 1}, {\"skuId\": \"SKU\"}, {\"skuId\": \"SKU\", \"qty\": 0}):
    error(call(\"POST\", body={\"items\": [item]}), 400, 40002, \"invalid item\")
items = [{\"skuId\": \"A\", \"qty\": \"2\"}, {\"skuId\": \"B\", \"qty\": 3}]
assert success(call(\"POST\", body={\"items\": items}))[\"items\"] == [
    {\"skuId\": \"A\", \"qty\": 2}, {\"skuId\": \"B\", \"qty\": 3}]
assert success(call(\"POST\", body={\"items\": items, \"remark\": None, \"couponCode\": \"\"})) == {
    \"orderId\": sample[\"orderId\"], \"status\": \"CREATED\",
    \"items\": [{\"skuId\": \"A\", \"qty\": 2}, {\"skuId\": \"B\", \"qty\": 3}], \"remark\": None, \"couponCode\": \"\"}
assert success(call(\"POST\", body={\"items\": items}))[\"remark\"] == \"\"
assert success(call(\"GET\", \"/{orderId}\", order_id=\"O1\")) == {
    \"orderId\": \"O1\", \"status\": \"CREATED\", \"items\": [], \"remark\": \"\"}
error(call(\"GET\", \"/{orderId}\", order_id=\"o1\"), 404, 40400, \"order not found\")
assert success(call(\"GET\")) == {\"page\": 1, \"size\": 20, \"total\": 0, \"list\": []}
for status_filter in (\"\", *STATUSES):
    assert success(call(\"GET\", args={\"page\": \"2\", \"size\": \"101\", \"status\": status_filter})) == {
        \"page\": 2, \"size\": 100, \"total\": 0, \"list\": []}
error(call(\"GET\", args={\"status\": \"created\"}), 400, 40003, \"invalid status\")
for body, reason in ((None, None), ({}, None), ({\"reason\": None}, None), ({\"reason\": \"\"}, \"\"), ({\"reason\": \"重复下单\"}, \"重复下单\")):
    assert success(call(\"POST\", \"/{orderId}/cancel\", body=body, order_id=\"x1\")) == {
        \"orderId\": \"x1\", \"status\": \"CANCELLED\", \"reason\": reason}
for method, kwargs, expected in (
    (\"POST\", {\"body\": {\"items\": [{\"skuId\": \"SKU\", \"qty\": None}]}}, TypeError),
    (\"GET\", {\"args\": {\"size\": \"\"}}, ValueError),
):
    try:
        call(method, **kwargs)
    except expected:
        pass
    else:
        raise AssertionError(\"Expected an unhandled conversion error\")

print(\"Passed: 4 route registrations and anchors, documented example, authentication, validation errors, defaults, pagination, response shapes and enums (Flask substitute).\")
